import{_ as i,o as n,c as s,ah as t}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"Technische Vision: Die Akustik des Mysteriums","description":"Wie wir die Stimmen von Diehl, Minichmayr und Masucci mittels modernster KI zum Klingen bringen.","frontmatter":{"title":"Technische Vision: Die Akustik des Mysteriums","description":"Wie wir die Stimmen von Diehl, Minichmayr und Masucci mittels modernster KI zum Klingen bringen.","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-02-27-technische-vision-audio.md","filePath":"logbuch/2026-02-27-technische-vision-audio.md"}'),r={name:"logbuch/2026-02-27-technische-vision-audio.md"};function a(o,e,h,d,c,l){return n(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="technische-vision-die-akustik-des-mysteriums" tabindex="-1">Technische Vision: Die Akustik des Mysteriums <a class="header-anchor" href="#technische-vision-die-akustik-des-mysteriums" aria-label="Permalink to &quot;Technische Vision: Die Akustik des Mysteriums&quot;">​</a></h1><p>Um die Texte unseres Hörbuch-Showcase in echte Audio-Erlebnisse zu verwandeln, setzen wir auf einen hochspezialisierten Workflow. Eine Mockumentary lebt von der Atmosphäre – das bloße Vorlesen von Text reicht nicht aus.</p><h2 id="das-audio-setup" tabindex="-1">Das Audio-Setup <a class="header-anchor" href="#das-audio-setup" aria-label="Permalink to &quot;Das Audio-Setup&quot;">​</a></h2><h3 id="_1-voice-engineering-die-charaktere" tabindex="-1">1. Voice Engineering (Die Charaktere) <a class="header-anchor" href="#_1-voice-engineering-die-charaktere" aria-label="Permalink to &quot;1. Voice Engineering (Die Charaktere)&quot;">​</a></h3><p>Wir nutzen <strong>ElevenLabs Studio 3.0</strong> als zentrale Produktionsplattform.</p><ul><li><strong>Professional Voice Cloning (PVC):</strong> Die Stimmen von Birgit Minichmayr und August Diehl erfordern höchste emotionale Varianz. Durch PVC können wir sicherstellen, dass Heidis Arroganz und August W.s Hektik authentisch klingen.</li><li><strong>Modell-Wahl:</strong> Für die Dialoge nutzen wir das <strong>V3 (Expressive)</strong> Modell, das am besten auf subtile emotionale Nuancen reagiert.</li></ul><h3 id="_2-sounddesign-die-atmosphare" tabindex="-1">2. Sounddesign (Die Atmosphäre) <a class="header-anchor" href="#_2-sounddesign-die-atmosphare" aria-label="Permalink to &quot;2. Sounddesign (Die Atmosphäre)&quot;">​</a></h3><p>Ein Hörbuch über das Horten-Vermögen muss nach Geld riechen – oder zumindest so klingen.</p><ul><li><strong>Layering:</strong> In der Studio-Timeline legen wir dezente Atmo-Sounds unter die Stimmen. Das sanfte Plätschern des Wörthersees für Heidi, das harte Klacken einer 1930er-Schreibmaschine für Helmut und nervöse Smartphone-Vibrationen für die Szenen in Linz.</li><li><strong>KI-Interferenzen:</strong> Die Stimmen von Grok und Gemini erhalten einen leicht synthetischen, aber dennoch hochauflösenden „Digital-Glow“, um ihre Rolle als Beobachter aus dem Äther zu betonen.</li></ul><h3 id="_3-speech-to-speech-die-regie" tabindex="-1">3. Speech-to-Speech (Die Regie) <a class="header-anchor" href="#_3-speech-to-speech-die-regie" aria-label="Permalink to &quot;3. Speech-to-Speech (Die Regie)&quot;">​</a></h3><p>Falls die KI eine bestimmte Betonung (z.B. eine besonders sarkastische Spitze) nicht sofort trifft, nutzen wir <strong>Speech-to-Speech</strong>. Dabei spreche ich (oder Volti) die Zeile mit der gewünschten Intonation ein, und die KI übernimmt diese Dynamik eins-zu-eins in der Zielstimme.</p><h2 id="das-ziel" tabindex="-1">Das Ziel <a class="header-anchor" href="#das-ziel" aria-label="Permalink to &quot;Das Ziel&quot;">​</a></h2><p>Das Ergebnis wird ein immersives Hörspiel sein, das die Grenzen zwischen Dokumentation und Fiktion akustisch verschwimmen lässt. Ein Archiv des Schweigens, das man hören kann.</p><p><em>Dokumentiert von Gemini CLI. Februar 2026.</em></p>',14)])])}const g=i(r,[["render",a]]);export{m as __pageData,g as default};
